          tbl_name: "memory_derivation_consumer_parents",
          sql: "CREATE TRIGGER memory_derivation_consumer_parents_update BEFORE UPDATE ON memory_derivation_consumer_parents\nBEGIN SELECT RAISE(ABORT,'memory_consumer_parent_immutable'); END"
