          tbl_name: "memory_derivation_results",
          sql: "CREATE TRIGGER memory_derivation_consumer_result_delete BEFORE DELETE ON memory_derivation_results\nBEGIN UPDATE memory_derivation_consumers SET state='retired',retired_at=MAX(created_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))\n WHERE state='active' AND job_id=OLD.job_id; END"
