        memory_derivation_grant_cap_floor: [
          {
            type: "trigger",
            name: "memory_derivation_grant_cap_floor",
            tbl_name: "memory_derivation_grants",
            sql: "CREATE TRIGGER memory_derivation_grant_cap_floor AFTER INSERT ON memory_derivation_grants\nBEGIN\n INSERT INTO memory_derivation_month_caps(payer_id,period,cap_microusd)\n SELECT NEW.payer_user_id,substr(NEW.consented_at,1,7),(SELECT MIN(monthly_cap_microusd) FROM memory_derivation_grants WHERE actor_user_id=NEW.payer_user_id AND substr(consented_at,1,7)=substr(NEW.consented_at,1,7))\n WHERE NOT EXISTS(SELECT 1 FROM memory_derivation_month_caps WHERE payer_id=NEW.payer_user_id AND period=substr(NEW.consented_at,1,7));\n UPDATE memory_derivation_month_caps SET cap_microusd=(SELECT MIN(monthly_cap_microusd) FROM memory_derivation_grants WHERE actor_user_id=NEW.payer_user_id AND substr(consented_at,1,7)=substr(NEW.consented_at,1,7))\n WHERE payer_id=NEW.payer_user_id AND period=substr(NEW.consented_at,1,7) AND cap_microusd>(SELECT MIN(monthly_cap_microusd) FROM memory_derivation_grants WHERE actor_user_id=NEW.payer_user_id AND substr(consented_at,1,7)=substr(NEW.consented_at,1,7)); END"
          }
        ],
