        memory_derivation_finance_immutable: [
          {
            type: "trigger",
            name: "memory_derivation_finance_immutable",
            tbl_name: "memory_derivation_finance",
            sql: "CREATE TRIGGER memory_derivation_finance_immutable BEFORE UPDATE ON memory_derivation_finance WHEN NEW.finance_id IS NOT OLD.finance_id OR NEW.payer_id IS NOT OLD.payer_id OR NEW.period IS NOT OLD.period OR NEW.token_id IS NOT OLD.token_id OR NEW.cost_id IS NOT OLD.cost_id OR NEW.operation IS NOT OLD.operation OR NEW.provider IS NOT OLD.provider OR NEW.model IS NOT OLD.model OR NEW.terms_sha256 IS NOT OLD.terms_sha256 OR NEW.request_sha256 IS NOT OLD.request_sha256 OR NEW.input_price IS NOT OLD.input_price OR NEW.cached_input_price IS NOT OLD.cached_input_price OR NEW.output_price IS NOT OLD.output_price OR NEW.maximum_input IS NOT OLD.maximum_input OR NEW.maximum_output IS NOT OLD.maximum_output OR NEW.maximum_tokens IS NOT OLD.maximum_tokens OR NEW.maximum_microusd IS NOT OLD.maximum_microusd OR NEW.authorized_cap_microusd IS NOT OLD.authorized_cap_microusd OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.project_access_id IS NOT OLD.project_access_id OR NEW.pilot_cohort_id IS NOT OLD.pilot_cohort_id OR NEW.created_at IS NOT OLD.created_at OR OLD.admission_closed_at IS NOT NULL AND NEW.admission_closed_at IS NOT OLD.admission_closed_at OR OLD.dispatch_token IS NOT NULL AND (NEW.dispatch_token IS NOT OLD.dispatch_token OR NEW.dispatched_at IS NOT OLD.dispatched_at)\nBEGIN SELECT RAISE(ABORT,'memory_finance_immutable'); END"
          }
        ],
        memory_derivation_finance_admit: [
          {
            type: "trigger",
            name: "memory_derivation_finance_admit",
            tbl_name: "memory_derivation_finance",
            sql: "CREATE TRIGGER memory_derivation_finance_admit BEFORE INSERT ON memory_derivation_finance\nBEGIN \n SELECT CASE WHEN NEW.dispatch_token IS NULL AND NEW.dispatched_at IS NULL AND NEW.admission_closed_at IS NULL\n AND NEW.period=strftime('%Y-%m','now') AND NEW.created_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now')\n AND NOT EXISTS(SELECT 1 FROM budget_reservations WHERE reservation_id IN(NEW.token_id,NEW.cost_id))\n AND NOT EXISTS(SELECT 1 FROM cost_budget_reservations WHERE reservation_id IN(NEW.token_id,NEW.cost_id))\n AND NOT EXISTS(SELECT 1 FROM project_budget_reservation_scopes WHERE reservation_id IN(NEW.token_id,NEW.cost_id))\n AND NOT EXISTS(SELECT 1 FROM pilot_cost_reservation_scopes WHERE reservation_id IN(NEW.token_id,NEW.cost_id))\n AND EXISTS(SELECT 1 FROM memory_derivation_month_caps cap WHERE cap.payer_id=NEW.payer_id AND cap.period=NEW.period\n   AND cap.cap_microusd<=NEW.authorized_cap_microusd\n   AND NOT EXISTS(SELECT 1 FROM memory_derivation_grants prior WHERE prior.actor_user_id=NEW.payer_id AND substr(prior.consented_at,1,7)=NEW.period AND prior.monthly_cap_microusd<cap.cap_microusd)\n   AND NEW.maximum_microusd+COALESCE((SELECT SUM(CASE WHEN unused.finance_id IS NOT NULL THEN 0 WHEN usage.finance_id IS NOT NULL THEN usage.used_microusd ELSE existing.maximum_microusd END)\n FROM memory_derivation_finance existing LEFT JOIN memory_derivation_usage usage ON usage.finance_id=existing.finance_id\n LEFT JOIN memory_derivation_no_dispatch unused ON unused.finance_id=existing.finance_id WHERE existing.payer_id=NEW.payer_id AND existing.period=NEW.period),0)<=cap.cap_microusd)\n THEN 1 ELSE RAISE(ABORT,'memory_finance_admission_unavailable') END; END"
          }
        ],
