            sql: "CREATE TRIGGER memory_derivation_user_control_source_update BEFORE UPDATE ON private_content\nBEGIN DELETE FROM memory_derivation_user_controls WHERE source_content_ref IN(OLD.content_id,NEW.content_id); END"
